45	// const isRecentVerificationRequest = (event: EventTimelineItem): boolean => {
46	//   const eventTimestamp = Number(event.timestamp);
47	//   const now = Date.now();
48	//   const age = now - eventTimestamp;
49	//   return age < VERIFICATION_REQUEST_MAX_AGE_MS;
50	// };
51	
52	interface Props {
53	  room: RoomInterface | undefined;
54	  roomId: string;
55	}
56	
57	const TIMELINE_PAGE_SIZE = 20;
58	const MIN_INITIAL_EVENTS = 10;
59	const ENABLE_TIMELINE_DEBUG = __DEV__;
60	
61	export const useRoomTimeline = ({ room, roomId }: Props) => {
62	  const [events, setEvents] = useState<EventTimelineItem[]>([]);
63	  /** Track processed verification request IDs to avoid duplicates */
64	  // const processedVerificationRequestsRef = useRef<Set<string>>(new Set());
65	  const eventIdsRef = useRef<Set<string>>(new Set());
66	  const timelineItemsRef = useRef<Array<EventTimelineItem | null>>([]);
67	  const timelineRef = useRef<TimelineInterface | null>(null);
68	  const isPaginatingRef = useRef(false);
69	  const reachedStartRef = useRef(false);
70	  // const setVerificationStatus = useSetAtom(MatrixAtoms.verificationStatus);
71	  const setPinnedEventIds = useSetAtom(TimelineAtoms.pinnedEventIds);
72	  const [isDirect, setIsDirect] = useState(false);
73	  /** FIFO queue of transactionIds for in-flight own messages, used to match the final echo Set diff */
74	  const pendingTransactionIdsQueue = useRef<string[]>([]);
75	  const rebuildTimerRef = useRef<ReturnType<typeof setTimeout>>(undefined);
76	
77	  const toEventItem = (item: TimelineItemInterface): EventTimelineItem | null =>
78	    item.asEvent() ?? null;
79	
80	  const rebuildEventsFromTimelineItems = useCallback(() => {
81	    const seenIds = new Set<string>();
82	    const nextEvents: EventTimelineItem[] = [];
83	
84	    for (const item of timelineItemsRef.current) {
85	      if (!item) continue;
86	      const key = getItemUniqueKey(item);
87	      if (key) {
88	        if (seenIds.has(key)) continue;
89	        seenIds.add(key);
90	      }
91	      nextEvents.push(item);
92	    }
93	
94	    eventIdsRef.current = seenIds;
95	    setEvents(nextEvents);
96	  }, []);
97	
98	  //Remove for now verification requests
99	  // const handleVerificationRequest = (info: {
100	  //   senderId: string;
101	  //   flowId: string;
102	  // }) => {
103	  //   setVerificationStatus("incomingRequest");
104	  //   NavigationContainerRef.navigate("verifyUser", {
105	  //     userId: info.senderId,
106	  //     flowId: info.flowId,
107	  //   });
108	  // };
109	
110	  // const checkForVerificationRequests = useCallback(
111	  //   (incoming: EventTimelineItem[]) => {
112	  //     for (const event of incoming) {
113	  //       if (event.isOwn) continue;
114	
115	  //       if (
116	  //         !isVerificationRequest(event) ||
117	  //         !isRecentVerificationRequest(event)
118	  //       ) {
119	  //         continue;
120	  //       }
121	
122	  //       const flowId = getEventId(event);
123	  //       if (!flowId) continue;
124	
125	  //       if (processedVerificationRequestsRef.current.has(flowId)) continue;
126	
127	  //       processedVerificationRequestsRef.current.add(flowId);
128	
129	  //       handleVerificationRequest({
130	  //         senderId: event.sender,
131	  //         flowId,
132	  //       });
133	
134	  //       // Only handle one at a time
135	  //       break;
136	  //     }
137	  //   },
138	  //   [],
139	  // );
140	
141	  const markAsRead = useCallback(async () => {
142	    if (!room) return;
143	    if (AppState.currentState !== "active") return;
144	
145	    try {
146	      await room.markAsRead(ReceiptType.Read);
147	    } catch (error) {
148	      console.error("Failed to mark room as read:", error);
149	    }
150	  }, [room]);
151	
152	  const loadMoreMessages = useCallback(async () => {
153	    if (!timelineRef.current || isPaginatingRef.current || reachedStartRef.current) return;
154	
155	    isPaginatingRef.current = true;
156	
157	    try {
158	      const hitStart = await timelineRef.current.paginateBackwards(TIMELINE_PAGE_SIZE);
159	      if (hitStart) {
160	        reachedStartRef.current = true;
161	      }
162	    } catch (error) {
163	      console.error("Failed to load more messages:", error);
164	    } finally {
165	      isPaginatingRef.current = false;
166	    }
167	  }, []);
168	
169	  useEffect(() => {
170	    if (!room) return;
171	    setPinnedEventIds([]);
172	    TimelineService.getPinnedEventIds(roomId)
173	      .then(setPinnedEventIds)
174	      .catch(console.error);
175	  }, [room, roomId, setPinnedEventIds]);
176	
177	  useEffect(() => {
178	    if (!room) return;
179	
180	    // Reset state when room changes
181	    setEvents([]);
182	    timelineItemsRef.current = [];
183	    eventIdsRef.current.clear();
184	    pendingTransactionIdsQueue.current = [];
185	
186	    let timelineListenerHandle: TaskHandleInterface | null = null;
187	    let isDisposed = false;
188	
189	    const initRoomTimeline = async () => {
190	      try {
191	        const timeline = await room.timelineWithConfiguration({
192	          focus: new TimelineFocus.Live({ hideThreadedEvents: false }),
193	          filter: new TimelineFilter.All(),
194	          internalIdPrefix: undefined,
195	          dateDividerMode: DateDividerMode.Daily,
196	          trackReadReceipts: TimelineReadReceiptTracking.AllEvents,
197	          reportUtds: false,
198	        });
199	
200	        // Store timeline in ref for reuse in pagination
201	        timelineRef.current = timeline;
202	
203	        // Set up listener BEFORE paginateBackwards so the SDK's initial
204	        // cached diffs (from SQLite) are received immediately — no network needed.
205	        // Set up timeline listener for real-time updates
206	        timelineListenerHandle = await timeline.addListener({
207	          onUpdate: (diffs) => {
208	            const beforeCount = timelineItemsRef.current.length;
209	            diffs.forEach((diff) => {
210	              const change = diff.tag;
211	              const timelineItems = timelineItemsRef.current;
212	              switch (change) {
213	                case TimelineDiff_Tags.Append: {
214	                  if (diff.inner.values.length > 0) {
215	                    timelineItems.push(...diff.inner.values.map(toEventItem));
216	                  }
217	                  break;
218	                }
219	                case TimelineDiff_Tags.Insert: {
220	                  const { index, value } = diff.inner;
221	                  timelineItems.splice(index, 0, toEventItem(value));
222	                  break;
223	                }
224	                case TimelineDiff_Tags.Set: {
225	                  const { index, value } = diff.inner;
226	                  const ev = toEventItem(value);
227	                  timelineItems[index] = ev;
228	
229	                  // transactionId -> eventId transition can arrive in an order where
230	                  // a stale local echo still exists elsewhere in the list.
231	                  if (
232	                    ev?.isOwn &&
233	                    !ev.localSendState &&
234	                    pendingTransactionIdsQueue.current.length > 0
235	                  ) {
236	                    const txId = pendingTransactionIdsQueue.current.shift();
237	                    if (txId) {
238	                      const txIndex = timelineItems.findIndex((item) => {
239	                        if (!item) return false;
240	                        return getItemUniqueKey(item) === txId;
241	                      });
242	                      if (txIndex !== -1) {
243	                        timelineItems[txIndex] = ev;
244	                      }
245	                    }
246	                  }
247	                  break;
248	                }
249	                case TimelineDiff_Tags.Remove: {
250	                  const { index: removeIndex } = diff.inner;
251	                  if (removeIndex >= 0 && removeIndex < timelineItems.length) {
252	                    timelineItems.splice(removeIndex, 1);
253	                  }
254	                  break;
255	                }
256	                case TimelineDiff_Tags.PushFront: {
257	                  const { value } = diff.inner;
258	                  timelineItems.unshift(toEventItem(value));
259	                  break;
260	                }
261	                case TimelineDiff_Tags.PushBack: {
262	                  const { value } = diff.inner;
263	                  const ev = toEventItem(value);
264	                  timelineItems.push(ev);
265	                  if (ev) {
266	                    const txId = getTransactionId(ev);
267	                    if (txId) {
268	                      pendingTransactionIdsQueue.current.push(txId);
269	                    }
270	                  }
271	                  break;
272	                }
273	                case TimelineDiff_Tags.PopFront: {
274	                  timelineItems.shift();
275	                  break;
276	                }
277	                case TimelineDiff_Tags.PopBack: {
278	                  timelineItems.pop();
279	                  break;
280	                }
281	                case TimelineDiff_Tags.Reset: {
282	                  const resetItems = diff.inner.values;
283	                  pendingTransactionIdsQueue.current = [];
284	                  timelineItemsRef.current = resetItems.map(toEventItem);
285	
286	                  const eventItems = timelineItemsRef.current.filter(
287	                    (i): i is EventTimelineItem => !!i,
288	                  );
289	                  pendingTransactionIdsQueue.current = eventItems
290	                    .map(getTransactionId)
291	                    .filter((id): id is string => !!id);
292	                  break;
293	                }
294	                case TimelineDiff_Tags.Truncate: {
295	                  const { length: cut } = diff.inner;
296	                  timelineItems.length = cut;
297	                  break;
298	                }
299	                case TimelineDiff_Tags.Clear: {
300	                  timelineItemsRef.current = [];
301	                  pendingTransactionIdsQueue.current = [];
302	                  eventIdsRef.current = new Set();
303	                  setEvents([]);
304	                  break;
305	                }
306	                default:
307	                  console.log("Unknown timeline change type:", change);
308	              }
309	            });
310	
311	            if (diffs.some((diff) => diff.tag !== TimelineDiff_Tags.Clear)) {
312	              if (rebuildTimerRef.current) clearTimeout(rebuildTimerRef.current);
313	              rebuildTimerRef.current = setTimeout(
314	                rebuildEventsFromTimelineItems,
315	                0,
316	              );
317	            }
318	
319	            if (ENABLE_TIMELINE_DEBUG) {
320	              const afterCount = timelineItemsRef.current.length;
321	              const tags = diffs.map((d) => d.tag).join(", ");
322	              console.log(
323	                `[TimelineDebug][${roomId}] diffs=[${tags}] items ${beforeCount}->${afterCount}`,
324	              );
325	            }
326	
327	          },
328	        });
329	
330	        // Paginate after the listener is set up so events flow through it.
331	        // Loop until we have at least MIN_INITIAL_EVENTS or reach the start.
332	        isPaginatingRef.current = true;
333	        (async () => {
334	          try {
335	            let hitStart = false;
336	            while (!isDisposed && !hitStart) {
337	              hitStart = await timeline.paginateBackwards(TIMELINE_PAGE_SIZE);
338	              if (hitStart) {
339	                reachedStartRef.current = true;
340	                break;
341	              }
342	              const eventCount = timelineItemsRef.current.filter(Boolean).length;
343	              if (eventCount >= MIN_INITIAL_EVENTS) break;
344	            }
345	          } catch (error) {
346	            if (!isDisposed) {
347	              console.warn("Failed to load initial messages:", error);
348	            }
349	          } finally {
350	            isPaginatingRef.current = false;
351	          }
352	        })();
353	      } catch (error) {
354	        console.error("Failed to initialize room timeline:", error);
355	        offlineToastHelper("Failed to load the messages. Please try again.");
356	        NavigationContainerRef.goBack();
357	        return null;
358	      }
359	    };
360	
361	    initRoomTimeline();
362	
363	    return () => {
364	      isDisposed = true;
365	      timelineListenerHandle?.cancel?.();
366	      if (rebuildTimerRef.current) clearTimeout(rebuildTimerRef.current);
367	      timelineRef.current = null;
368	      timelineItemsRef.current = [];
369	      isPaginatingRef.current = false;
370	      reachedStartRef.current = false;
371	    };
372	  }, [rebuildEventsFromTimelineItems, room, roomId]);
373	
374	  useEffect(() => {
375	    markAsRead().catch(console.error);
376	    room?.isDirect().then(setIsDirect).catch(console.error);
377	  }, [room, markAsRead]);
378	
379	  return {
380	    events,
381	    timelineRef,
382	    isPaginatingRef,
383	    reachedStartRef,
384	    isDirect,
385	    loadMoreMessages,
386	    markAsRead,
387	  };
388	};
